-- =====================================================================
-- DỮ LIỆU MẪU CHO DATABASE: multichannel_sales
-- Sinh tự động (Node.js, seeded random) để phục vụ demo/test báo cáo.
-- Giả định: các bảng đang RỖNG và cột IDENTITY bắt đầu từ 1, tăng dần 1
-- đơn vị mỗi dòng insert theo đúng thứ tự bên dưới (không insert cột
-- IDENTITY, để SQL Server tự sinh id) -- nhờ vậy các FK literal trong
-- script này (region_id, store_id, category_id, product_id,
-- promotion_id, customer_id, order_id...) khớp với id thực tế được tạo ra.
-- =====================================================================

